using System.Text.Json;
using DualOntologyWorldEngine.Story;
using DualOntologyWorldEngine.Core;
var json=File.ReadAllText(args[0]);int failures=0;
Console.WriteLine("SCOPE: development world-script examples; not formal chapter migration or blind play.");
void Check(string name,Action test){try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+" "+e);}}
void Assert(bool value,string message="assertion"){if(!value)throw new Exception(message);}
void Reject(Action a){bool rejected=false;try{a();}catch{rejected=true;}Assert(rejected,"expected rejection");}
WorldSession New(){var s=new WorldSession();s.Load(WorldScriptDocument.Parse(json)[0]);return s;}
const string player="character.detective",guard="character.guard",bolt="object.inner_bolt";
AvailableCandidate[] Offer(WorldSession s)=>s.Process(new RequestCandidates(player,bolt)).OfType<CandidatesAvailable>().Single().Candidates.ToArray();
void See(WorldSession s,string who){s.Process(new VerifiedPerception(who,[bolt,player,guard,"room.foyer"]));}
Check("actual compiled chapters",()=>Assert(WorldScriptDocument.Parse(json).Select(c=>c.Id).SequenceEqual(new[]{"arrival","morning"})));
Check("malformed Int32 input rejected before chapter mutation",()=>{using var s=new WorldSession();var chapter=WorldScriptDocument.Parse(json)[0];chapter.Entities.Single(e=>e.Id==bolt).Properties["state:large"]=new(){Type="integer",Value=JsonSerializer.SerializeToElement(2147483648L)};Reject(()=>s.Load(chapter));Assert(s.LoadedChapters.Count==0);});
Check("only applicable player candidates",()=>{using var s=New();Assert(Offer(s).Length==0);See(s,player);Assert(Offer(s).Select(c=>c.Id).SequenceEqual(new[]{"arrival:inspect_inner_bolt"}));});
Check("Core decision changes with subjective strategy",()=>{using var s=New();See(s,guard);var a=s.AssessReactions(guard,"inspect_inner_bolt");Console.WriteLine(JsonSerializer.Serialize(a));var first=s.Process(new RequestReaction(guard,"inspect_inner_bolt")).OfType<CandidateActionStarted>().Single();s.Process(new AdvanceWorld(3));s.RememberState(guard,guard,"cautious",0);Console.WriteLine(JsonSerializer.Serialize(s.AssessReactions(guard,"inspect_inner_bolt")));var second=s.Process(new RequestReaction(guard,"inspect_inner_bolt")).OfType<CandidateActionStarted>().Single();Assert(first.CandidateId!=second.CandidateId);});
Check("unknown reaction not forced",()=>{using var s=New();Assert(s.Process(new RequestReaction(guard,"inspect_inner_bolt")).Single() is NoApplicableCandidate);});
Check("identity and state survive chapter extend",()=>{using var s=New();var e=s.Entity(bolt);var c=s.Character(player);var soul=c.Soul;var self=c.Self;e.Get<StateProperty>()!.Values[new Tag("engaged")]=7;s.Load(WorldScriptDocument.Parse(json)[1]);Assert(ReferenceEquals(e,s.Entity(bolt))&&ReferenceEquals(soul,s.Character(player).Soul)&&ReferenceEquals(self,s.Character(player).Self));Assert(e.Get<StateProperty>()!.Values[new Tag("engaged")]==7);});
Check("duplicate and missing dependency atomic",()=>{using var s=New();Reject(()=>s.Load(WorldScriptDocument.Parse(json)[0]));Assert(s.LoadedChapters.Count==1);using var fresh=new WorldSession();Reject(()=>fresh.Load(WorldScriptDocument.Parse(json)[1]));Assert(fresh.LoadedChapters.Count==0);});
Check("invalid reference and action atomic",()=>{foreach(var action in new[]{false,true}){using var s=New();var ch=WorldScriptDocument.Parse(json)[1];if(action)ch.Candidates[0].Response.Add(new(){Op="call",Name="evil"});else ch.Candidates[0].Target="world:missing";Reject(()=>s.Load(ch));Assert(s.CurrentChapter=="arrival"&&s.LoadedChapters.Count==1);Assert(!s.Character(player).Body.Get<StateProperty>()!.Values.ContainsKey(new Tag("trust_huo")));}});
Check("duplicate and expired selections",()=>{using var s=New();See(s,player);var old=Offer(s).Single();var current=Offer(s).Single();Reject(()=>s.Process(new SelectCandidate(old.Token)));Assert(s.Process(new SelectCandidate(current.Token)).OfType<CandidateActionStarted>().Count()==1);Reject(()=>s.Process(new SelectCandidate(current.Token)));Assert(s.Process(new AdvanceWorld(3)).OfType<CandidateActionFinished>().Count()==1);});
Check("semantic output assembly has no Godot reference",()=>Assert(!typeof(WorldOutput).Assembly.GetReferencedAssemblies().Any(a=>a.Name!.Contains("Godot"))));
Check("legacy behavior rejected",()=>Reject(()=>WorldScriptDocument.Parse(json.Replace("\"chapters\":","\"behavior\":[{}],\"chapters\":"))));
Check("three valued and subjective applicability",()=>{foreach(var mode in new[]{"or","not","belief"}){var ch=WorldScriptDocument.Parse(json)[0];var c=ch.Candidates[0];c.Target=null;c.Response=c.Response.Where(x=>x.Op=="line").ToList();DialogueExpression L(object v)=>new(){Value=JsonSerializer.SerializeToElement(v)};var unknown=new DialogueExpression{Op="call",Name="known",Args=[L("world:object.inner_bolt")]};c.Applicability=mode=="belief"?new(){Op="eq",Args=[new(){Op="call",Name="state",Args=[L("world:character.guard"),L("cautious")]},L(1)]}:new(){Op=mode,Args=mode=="or"?[L(true),unknown]:[unknown]};using var s=new WorldSession();s.Load(ch);var offered=s.Process(new RequestCandidates(mode=="belief"?guard:player)).OfType<CandidatesAvailable>().Single().Candidates;Assert(offered.Count==(mode=="not"?0:1),mode);if(mode=="belief"){s.Process(new SelectCandidate(offered.Single().Token));Assert(s.Process(new AdvanceWorld(3)).OfType<CandidateActionFinished>().Single().Succeeded);Assert(!s.Entity(guard).Get<StateProperty>()!.Values.ContainsKey(new Tag("cautious")));}}});
Check("false belief cannot peek objective",()=>{var ch=WorldScriptDocument.Parse(json)[0];var c=ch.Candidates[0];c.Applicability=new(){Op="eq",Args=[new(){Op="call",Name="state",Args=[new(){Value=JsonSerializer.SerializeToElement("world:object.inner_bolt")},new(){Value=JsonSerializer.SerializeToElement("engaged")}]},new(){Value=JsonSerializer.SerializeToElement(1)}]};using var s=new WorldSession();s.Load(ch);See(s,player);s.RememberState(player,bolt,"engaged",0);Assert(Offer(s).Length==0);Assert(s.Entity(bolt).Get<StateProperty>()!.Values[new Tag("engaged")]==1);});
Check("world candidate survives second chapter load",()=>{using var s=New();See(s,player);Assert(Offer(s).Any(c=>c.Id=="arrival:inspect_inner_bolt"));s.Load(WorldScriptDocument.Parse(json)[1]);Assert(Offer(s).Any(c=>c.Id=="arrival:inspect_inner_bolt"));});
Console.WriteLine($"RESULT failures={failures}");return failures==0?0:1;
